import sys
import math

def solve() -> None:
    input = sys.stdin.readline
    MOD = 998244353
    n, m = map(int, input().split())
    b = list(map(int, input().split()))

    # 1. 前缀和 P 与二次前缀和 Q
    P = [0] * (n + 1)
    Q = [0] * (n + 1)
    for i in range(1, n + 1):
        P[i] = P[i-1] + b[i-1]
        Q[i] = Q[i-1] + P[i]

    # 2. 计算 G[k] = W(k) mod MOD
    G = [0] * (n + 1)
    for k in range(1, n + 1):
        G[k] = (Q[n] - Q[k-1] - Q[n-k]) % MOD

    # 3. 埃氏筛，标记素数长度
    is_prime = [True] * (n + 1)
    if n >= 0:
        is_prime[0] = False
    if n >= 1:
        is_prime[1] = False
    for i in range(2, int(math.isqrt(n)) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False

    # 4. 前缀和 h[i]：前 i 个长度中素数长度对应的 G 值之和
    h = [0] * (n + 1)
    for i in range(1, n + 1):
        h[i] = h[i-1] + (G[i] if is_prime[i] else 0)
        if h[i] >= MOD:
            h[i] -= MOD

    # 5. 回答询问
    out_lines = []
    for _ in range(m):
        l, r = map(int, input().split())
        ans = (h[r] - h[l-1]) % MOD
        out_lines.append(str(ans))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
